import math
        import random
        import time

        LANGUAGE_WRAPPER = 'A right rectangular solid with base {a_cm} by {b_cm} centimeters and height {c_cm} centimeters rests on a horizontal surface. A point source of light is located x centimeters directly above a point of the top face that is {u_cm} centimeters from one side and {v_cm} centimeters from an adjacent side. The shadow on the horizontal surface, excluding the area directly beneath the solid, has area {shadow_area} square centimeters. Find the greatest integer that does not exceed {m_scale}x.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # choose dimensions with room for internal offsets
    while True:
        a = rng.randint(3, 25)
        b = rng.randint(3, 25)
        c = rng.randint(2, 40)
        # internal offsets u, v strictly inside the top face
        u = rng.randint(1, a - 1)
        v = rng.randint(1, b - 1)
        # choose integer t = c/x >= 2 to avoid triviality
        t = rng.randint(2, 40)
        # area formula: shadow_area = ab*(t^2 + 2t), independent of offsets
        shadow_area = a * b * (t * t + 2 * t)
        # choose scale factor
        m = rng.randint(500, 5000)
        # compute x = c/t
        x = c / t
        ans = math.floor(m * x)
        # sanity bounds on numerical size
        if shadow_area > 0 and ans >= 1 and ans <= 10**9:
            return {
                'a_cm': a,
                'b_cm': b,
                'c_cm': c,
                'u_cm': u,
                'v_cm': v,
                'shadow_area': shadow_area,
                'm_scale': m
            }

        import math

def verifier(assign):
    # basic presence and type checks
    req = ['a_cm', 'b_cm', 'c_cm', 'u_cm', 'v_cm', 'shadow_area', 'm_scale']
    for k in req:
        if k not in assign:
            # missing data
            return (False, None)
        if not isinstance(assign[k], int):
            # all slots are integers
            return (False, None)
    a = assign['a_cm']
    b = assign['b_cm']
    c = assign['c_cm']
    u = assign['u_cm']
    v = assign['v_cm']
    S = assign['shadow_area']
    m = assign['m_scale']
    # domain constraints
    if not (a >= 3 and b >= 3 and c >= 2 and m >= 1 and S > 0):
        return (False, None)
    if not (1 <= u <= a - 1 and 1 <= v <= b - 1):
        return (False, None)
    # recompute x from the derived formula
    # The perspective scale s satisfies s = 1 + c/x, and the shadow area excluding the base is S = ab (s^2 - 1)
    # Thus 1 + S/(ab) = s^2 = (1 + c/x)^2, so sqrt(1 + S/(ab)) = 1 + c/x
    try:
        M = S / (a * b)
    except ZeroDivisionError:
        return (False, None)
    if M <= 0:
        return (False, None)
    s_sq = 1 + M
    # numerical robustness: s should be > 1
    if s_sq <= 1:
        return (False, None)
    s = math.sqrt(s_sq)
    # ensure t = c/x = s - 1 is reasonably large (>= 2) to avoid trivial cases
    t = s - 1.0
    if t <= 1.999999:  # conservative float guard
        return (False, None)
    # compute x
    x = c / t
    if x <= 0:
        return (False, None)
    # answer
    answer = math.floor(m * x)
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

